_CUDA_SRC = r"""
#include <torch/extension.h>
#include <ATen/cuda/CUDAContext.h>
#include <cuda_runtime.h>

namespace {

constexpr int BM = 64;
constexpr int BN = 64;
constexpr int BK = 16;
constexpr int TX = 16;
constexpr int TY = 16;
constexpr int THREADS = TX * TY;
constexpr int RT = BM / TY;
constexpr int CT = BN / TX;

template <typename scalar_t>
__global__ void conv2d_implicit_gemm_kernel(
    const scalar_t* __restrict__ input,
    const scalar_t* __restrict__ weight,
    const scalar_t* __restrict__ bias,
    scalar_t* __restrict__ output,
    int batch,
    int in_channels,
    int out_channels,
    int height,
    int width,
    int out_h,
    int out_w,
    int kernel_h,
    int kernel_w,
    int stride_h,
    int stride_w,
    int pad_h,
    int pad_w,
    int dil_h,
    int dil_w,
    bool has_bias) {
  extern __shared__ char smem_raw[];
  scalar_t* As = reinterpret_cast<scalar_t*>(smem_raw);
  scalar_t* Bs = As + BK * BM;

  const int tid = threadIdx.y * blockDim.x + threadIdx.x;
  const int tx = threadIdx.x;
  const int ty = threadIdx.y;

  const int row0 = blockIdx.y * BM;
  const int64_t col0 = static_cast<int64_t>(blockIdx.x) * BN;

  const int khw = kernel_h * kernel_w;
  const int K = in_channels * khw;
  const int64_t out_spatial = static_cast<int64_t>(out_h) * out_w;
  const int64_t ncols = static_cast<int64_t>(batch) * out_spatial;
  const int64_t in_spatial = static_cast<int64_t>(height) * width;

  scalar_t acc[RT][CT];
#pragma unroll
  for (int i = 0; i < RT; ++i) {
#pragma unroll
    for (int j = 0; j < CT; ++j) {
      acc[i][j] = static_cast<scalar_t>(0);
    }
  }

  // Hoist per-thread invariant geometry out of the K-reduction loop.
  // Because THREADS is a multiple of BM and BN, each thread always maps
  // to the same smem tile row/column across all k0 iterations, so the
  // expensive column decode (64-bit div/mod) is done exactly once.
  constexpr int A_ELEMS = BK * BM / THREADS;
  constexpr int B_ELEMS = BK * BN / THREADS;
  constexpr int A_KSTEP = THREADS / BM;
  constexpr int B_KSTEP = THREADS / BN;
  const int a_m = tid % BM;
  const int a_kk0 = tid / BM;
  const int a_oc = row0 + a_m;
  const bool a_ok = a_oc < out_channels;
  const scalar_t* a_w = weight + (a_ok ? static_cast<int64_t>(a_oc) * K : 0);
  const int b_n = tid % BN;
  const int b_kk0 = tid / BN;
  const int64_t b_col = col0 + b_n;
  const bool b_ok = b_col < ncols;
  int b_img = 0;
  int b_h0 = 0;
  int b_w0 = 0;
  if (b_ok) {
    const int64_t n_img = b_col / out_spatial;
    const int64_t srem = b_col - n_img * out_spatial;
    const int oh = static_cast<int>(srem / out_w);
    const int ow = static_cast<int>(srem - static_cast<int64_t>(oh) * out_w);
    b_img = static_cast<int>(n_img);
    b_h0 = oh * stride_h - pad_h;
    b_w0 = ow * stride_w - pad_w;
  }
  for (int k0 = 0; k0 < K; k0 += BK) {
#pragma unroll
    for (int i = 0; i < A_ELEMS; ++i) {
      const int kk = a_kk0 + i * A_KSTEP;
      const int k = k0 + kk;
      scalar_t v = static_cast<scalar_t>(0);
      if (a_ok && k < K) {
        v = a_w[k];
      }
      As[kk * BM + a_m] = v;
    }
#pragma unroll
    for (int i = 0; i < B_ELEMS; ++i) {
      const int kk = b_kk0 + i * B_KSTEP;
      const int k = k0 + kk;
      scalar_t v = static_cast<scalar_t>(0);
      if (b_ok && k < K) {
        const int ic = k / khw;
        const int rem = k - ic * khw;
        const int r = rem / kernel_w;
        const int s = rem - r * kernel_w;
        const int ih = b_h0 + r * dil_h;
        const int iw = b_w0 + s * dil_w;
        if (ih >= 0 && ih < height && iw >= 0 && iw < width) {
          v = input[(static_cast<int64_t>(b_img) * in_channels + ic) * in_spatial +
                    static_cast<int64_t>(ih) * width + iw];
        }
      }
      Bs[kk * BN + b_n] = v;
    }
    __syncthreads();
    const int kmax = min(BK, K - k0);
    const int rloc = ty * RT;
    const int cloc = tx * CT;
    for (int kk = 0; kk < kmax; ++kk) {
      scalar_t a[RT];
      scalar_t b[CT];
      if constexpr (sizeof(scalar_t) == 4 && RT == 4 && CT == 4) {
        // Vectorized 16-byte shared-memory loads. Row strides (BM/BN) and
        // the per-thread offsets (rloc = ty*RT, cloc = tx*CT) are all
        // multiples of 4 elements, so these float4 loads are always aligned.
        // This cuts the number of L1/shared load transactions in the inner
        // GEMM loop by 4x, relieving the memory-throughput bottleneck.
        const float4 av = *reinterpret_cast<const float4*>(As + kk * BM + rloc);
        a[0] = static_cast<scalar_t>(av.x);
        a[1] = static_cast<scalar_t>(av.y);
        a[2] = static_cast<scalar_t>(av.z);
        a[3] = static_cast<scalar_t>(av.w);
        const float4 bv = *reinterpret_cast<const float4*>(Bs + kk * BN + cloc);
        b[0] = static_cast<scalar_t>(bv.x);
        b[1] = static_cast<scalar_t>(bv.y);
        b[2] = static_cast<scalar_t>(bv.z);
        b[3] = static_cast<scalar_t>(bv.w);
      } else {
#pragma unroll
        for (int i = 0; i < RT; ++i) {
          a[i] = As[kk * BM + rloc + i];
        }
#pragma unroll
        for (int j = 0; j < CT; ++j) {
          b[j] = Bs[kk * BN + cloc + j];
        }
      }
#pragma unroll
      for (int i = 0; i < RT; ++i) {
#pragma unroll
        for (int j = 0; j < CT; ++j) {
          acc[i][j] += a[i] * b[j];
        }
      }
    }
    __syncthreads();
  }

#pragma unroll
  for (int j = 0; j < CT; ++j) {
    const int64_t col = col0 + tx * CT + j;
    if (col >= ncols) {
      continue;
    }
    const int64_t n_img = col / out_spatial;
    const int64_t srem = col - n_img * out_spatial;
    const int oh = static_cast<int>(srem / out_w);
    const int ow = static_cast<int>(srem - static_cast<int64_t>(oh) * out_w);

#pragma unroll
    for (int i = 0; i < RT; ++i) {
      const int oc = row0 + ty * RT + i;
      if (oc < out_channels) {
        scalar_t v = acc[i][j];
        if (has_bias) {
          v += bias[oc];
        }
        output[(n_img * out_channels + oc) * out_spatial +
               static_cast<int64_t>(oh) * out_w + ow] = v;
      }
    }
  }
}

}  // namespace

at::Tensor conv2d_forward(
    const at::Tensor& input,
    const at::Tensor& weight,
    const at::Tensor& bias,
    int64_t stride_h,
    int64_t stride_w,
    int64_t pad_h,
    int64_t pad_w,
    int64_t dil_h,
    int64_t dil_w) {
  TORCH_CHECK(input.is_cuda(), "input must be CUDA");
  TORCH_CHECK(weight.is_cuda(), "weight must be CUDA");
  TORCH_CHECK(input.dim() == 4, "input must be NCHW");
  TORCH_CHECK(weight.dim() == 4, "weight must be OIHW");
  TORCH_CHECK(input.scalar_type() == weight.scalar_type(), "input/weight dtype mismatch");

  auto x = input.contiguous();
  auto w = weight.contiguous();

  const int batch = static_cast<int>(x.size(0));
  const int in_channels = static_cast<int>(x.size(1));
  const int height = static_cast<int>(x.size(2));
  const int width = static_cast<int>(x.size(3));
  const int out_channels = static_cast<int>(w.size(0));
  const int kernel_h = static_cast<int>(w.size(2));
  const int kernel_w = static_cast<int>(w.size(3));

  TORCH_CHECK(w.size(1) == in_channels, "weight in_channels mismatch");

  const int out_h = static_cast<int>(
      (height + 2 * pad_h - dil_h * (kernel_h - 1) - 1) / stride_h + 1);
  const int out_w = static_cast<int>(
      (width + 2 * pad_w - dil_w * (kernel_w - 1) - 1) / stride_w + 1);
  TORCH_CHECK(out_h > 0 && out_w > 0, "invalid output size");

  auto out = at::empty({batch, out_channels, out_h, out_w}, x.options());

  const bool has_bias = bias.defined() && bias.numel() > 0;
  at::Tensor b;
  if (has_bias) {
    b = bias.contiguous();
    TORCH_CHECK(b.is_cuda(), "bias must be CUDA");
    TORCH_CHECK(b.numel() == out_channels, "bias size mismatch");
  }

  const int64_t ncols = static_cast<int64_t>(batch) * out_h * out_w;
  dim3 block(TX, TY);
  dim3 grid(static_cast<unsigned>((ncols + BN - 1) / BN),
            static_cast<unsigned>((out_channels + BM - 1) / BM));

  auto stream = at::cuda::getCurrentCUDAStream();

  AT_DISPATCH_FLOATING_TYPES(x.scalar_type(), "conv2d_forward_cuda", [&] {
    const size_t smem = (BK * BM + BK * BN) * sizeof(scalar_t);
    conv2d_implicit_gemm_kernel<scalar_t><<<grid, block, smem, stream>>>(
        x.data_ptr<scalar_t>(),
        w.data_ptr<scalar_t>(),
        has_bias ? b.data_ptr<scalar_t>() : nullptr,
        out.data_ptr<scalar_t>(),
        batch,
        in_channels,
        out_channels,
        height,
        width,
        out_h,
        out_w,
        kernel_h,
        kernel_w,
        static_cast<int>(stride_h),
        static_cast<int>(stride_w),
        static_cast<int>(pad_h),
        static_cast<int>(pad_w),
        static_cast<int>(dil_h),
        static_cast<int>(dil_w),
        has_bias);
  });

  C10_CUDA_KERNEL_LAUNCH_CHECK();
  return out;
}
"""

_CPP_SRC = r"""
at::Tensor conv2d_forward(
    const at::Tensor& input,
    const at::Tensor& weight,
    const at::Tensor& bias,
    int64_t stride_h,
    int64_t stride_w,
    int64_t pad_h,
    int64_t pad_w,
    int64_t dil_h,
    int64_t dil_w);
"""

_ext = load_inline(
    name="model_new_conv2d_ext",
    cpp_sources=[_CPP_SRC],
    cuda_sources=[_CUDA_SRC],
    functions=["conv2d_forward"],
    extra_cuda_cflags=["-O3", "--use_fast_math"],
    verbose=False,
)


class ModelNew(nn.Module):
    def __init__(
        self,
        in_channels: int,
        out_channels: int,
        kernel_size: tuple,
        stride: int = 1,
        padding: tuple = (0, 0),
        dilation: tuple = (1, 1),
        bias: bool = False,
    ):
        super().__init__()
        self.in_channels = in_channels
        self.out_channels = out_channels
        self.kernel_size = kernel_size
        self.stride = stride
        self.padding = padding
        self.dilation = dilation

        self.conv2d = nn.Module()
        self.conv2d.weight = nn.Parameter(
            torch.empty(out_channels, in_channels, kernel_size[0], kernel_size[1])
        )
        if bias:
            self.conv2d.bias = nn.Parameter(torch.empty(out_channels))
        else:
            self.conv2d.register_parameter("bias", None)
        self.reset_parameters()

    def reset_parameters(self) -> None:
        init.kaiming_uniform_(self.conv2d.weight, a=math.sqrt(5))
        if self.conv2d.bias is not None:
            fan_in, _ = init._calculate_fan_in_and_fan_out(self.conv2d.weight)
            if fan_in != 0:
                bound = 1 / math.sqrt(fan_in)
                init.uniform_(self.conv2d.bias, -bound, bound)

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        if self.conv2d.bias is None:
            bias = torch.empty(0, device=x.device, dtype=x.dtype)
        else:
            bias = self.conv2d.bias
        return _ext.conv2d_forward(
            x,
            self.conv2d.weight,
            bias,
            self.stride,
            self.stride,
            self.padding[0],
            self.padding[1],
            self.dilation[0],
            self.dilation[1],
        )

